import importlib.util, json, re, subprocess, sys
from pathlib import Path

B = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location("rgc", B.parent / "scripts" / "rg-compare.py")
rgc = importlib.util.module_from_spec(spec)
spec.loader.exec_module(rgc)
BIN = {"main": str(B / "target-main/release/monokl"), "new": str(B / "target-new/release/monokl")}
rgc.configure(BIN["main"])


def tokens(s):
    out, i, n = [], 0, len(s)
    while i <= n:
        if i < n and s[i] == '"':
            j = i + 1
            while s[j] != '"':
                j += 2 if s[j] == "\\" else 1
            out.append(s[i : j + 1])
            i = j + 2
        else:
            j = s.find(",", i)
            if j < 0:
                j = n
            out.append(s[i:j])
            i = j + 1
    return out


def parse(out):
    rows = []
    for line in out.splitlines():
        if line.startswith("  ") and not line.startswith("   "):
            t = tokens(line[2:])
            if len(t) < 9:
                continue
            rows.append(dict(file=t[0].removeprefix("./"), l0=int(t[1]), l1=int(t[2]), kind=t[3], parent=t[4],
                             sig=t[5].strip('"') if t[5] != "null" else None, snip=t[6], rank=int(t[7]),
                             score=float(t[8])))
    return rows


def run(which, q, path):
    r = subprocess.run([BIN[which], "search", q, "."], cwd=path, capture_output=True, text=True)
    return parse(r.stdout)[:5]


queries = []
repos = {name: (name, lang, held) for name, url, sha, lang, held in rgc.repositories(None)}
for repo, words, file, symbol, member, held in rgc.question_rows(None):
    queries.append(dict(id=f"Q:{repo}:{words}", kind="question", repo=repo, q=words, exp_files=[file], exp_symbol=symbol,
                        member=member))
for name, url, sha, lang, held in rgc.repositories(None):
    if held:
        continue
    path = B / "repos" / name
    for term in rgc.sample_terms(path, 25, lang):
        defs, _ = rgc.split(rgc.definitions(term, path, lang), lang)
        queries.append(dict(id=f"I:{name}:{term}", kind="ident", repo=name, q=term, exp_files=sorted(defs),
                            exp_symbol=term, member=False))
res = []
for q in queries:
    path = B / "repos" / q["repo"]
    q["main"] = run("main", q["q"], path)
    q["new"] = run("new", q["q"], path)
    res.append(q)
json.dump(res, open(B / "results.json", "w"), indent=1)
print(len(res), sum(1 for q in res if q["main"][:1] != q["new"][:1] and (q["main"][:1] and q["new"][:1] and (q["main"][0]["file"], q["main"][0]["l0"]) != (q["new"][0]["file"], q["new"][0]["l0"]))))

