new='''    let variant = std::env::var("MK_V").unwrap_or_default();
    let nq = as_f64(query_terms.len());
    let nn = as_f64(name_tokens.len());
    let m = as_f64(matched);
    let bonus = if exact { 4.0 } else { 0.0 };
    let (r, p) = (recall, precision);
    let v = match variant.as_str() {
        // A: recall weighted above precision
        "A" => 1.0 + 2.0 * (r + 0.25 * p) / 1.25 + bonus,
        // B: precision scaled by recall
        "B" => 1.0 + 2.0 * (r + 0.5 * p * r) / 1.5 + bonus,
        // C: precision only for names of 2+ tokens (or exact)
        "C" => { let pp = if nn >= 2.0 || exact { p } else { 0.0 }; 1.0 + 2.0 * (r + 0.5 * pp) / 1.5 + bonus }
        // D: precision only when recall >= 0.5
        "D" => { let pp = if r >= 0.5 || exact { p } else { 0.0 }; 1.0 + 2.0 * (r + 0.5 * pp) / 1.5 + bonus }
