        "G" => { let pp = if m >= 2.0 || exact { p } else { 0.0 }; 1.0 + 2.0 * (r + 0.5 * pp) / 1.5 + bonus }
        // F: harmonic mean in place of precision
        "F" => { let f = if r + p > 0.0 { 2.0 * r * p / (r + p) } else { 0.0 }; 1.0 + 2.0 * (r + 0.5 * f) / 1.5 + bonus }
        // H: recall only plus exact
        "H" => 1.0 + 2.0 * r + bonus,
        // I: sqrt-recall scaled precision, recall weight 1
        "I" => { let _ = (nq, nn); 1.0 + 2.0 * (r + 0.5 * p * r.sqrt()) / 1.5 + bonus }
        _ => 1.0 + 2.0 * (r + 0.5 * p) / 1.5 + bonus,
    };
    round6(v)
}'''
assert old in s
open(p,'w').write(s.replace(old,new))
