import json, os, subprocess, sys
from concurrent.futures import ThreadPoolExecutor
D = "/Users/gabe/Projects/monokl/.claude/worktrees/agent-acf53a379d2e3861a/target/ev"
sys.path.insert(0, D)
B = "/Users/gabe/Projects/monokl/.claude/worktrees/agent-a26b382a3617839f4/blind"
BIN = "/Users/gabe/Projects/monokl/.claude/worktrees/agent-acf53a379d2e3861a/target/release/monokl"
res = json.load(open(B + "/results.json"))


def tokens(s):
    out, i, n = [], 0, len(s)
    while i <= n:
        if i < n and s[i] == '"':
            j = i + 1
            while s[j] != '"':
                j += 2 if s[j] == "\\" else 1
            out.append(s[i:j + 1]); i = j + 2
        else:
            j = s.find(",", i)
            if j < 0: j = n
            out.append(s[i:j]); i = j + 1
    return out


def parse(out):
    rows = []
    for line in out.splitlines():
        if line.startswith("  ") and not line.startswith("   "):
            t = tokens(line[2:])
            if len(t) < 9: continue
            rows.append(dict(file=t[0].removeprefix("./"), l0=int(t[1]), kind=t[3], sig=t[5].strip('"') if t[5] != "null" else None))
    return rows[:5]


def evaluate(label, env):
    e = dict(os.environ, **env)

    def one(q):
        r = subprocess.run([BIN, "search", q["q"], "."], cwd=B + "/repos/" + q["repo"], capture_output=True, text=True, env=e)
        return parse(r.stdout)
    with ThreadPoolExecutor(8) as ex:
        rows = list(ex.map(one, res))
    json.dump([dict(id=q["id"], rows=r) for q, r in zip(res, rows)], open(f"{D}/q_{label}.json", "w"))


if __name__ == "__main__":
    import an
    for spec in sys.argv[1:]:
        env = {"MK_V": "P"}
        for kv in spec.split(","):
            k, v = kv.split("=")
            env["MK_" + k.upper()] = v
        evaluate(spec, env)
        o = an.go(spec)
        print(spec, "kept", o["kept"], "fixed", o["fixed"], "lost", o["lost_better"], "eqmoved", [(x[0], x[1]) for x in o["eq"]],
              "dem", [d[0].split(":", 1)[1] for d in o["demoted"]], "moved", len(o["moved_unchanged"]), flush=True)

